  'chemcollective': {'en': 'Do titrations and other chemistry experiments in a virtual lab.', 'hi': 'आभासी प्रयोगशाला में अनुमापन और रसायन विज्ञान के अन्य प्रयोग करें।', 'kn': 'ವರ್ಚುವಲ್ ಪ್ರಯೋಗಾಲಯದಲ್ಲಿ ಟೈಟ್ರೇಷನ್‌ಗಳು ಮತ್ತು ಇತರ ರಸಾಯನಶಾಸ್ತ್ರ ಪ್ರಯೋಗಗಳನ್ನು ಮಾಡಿ.'},
  'circuitjs': {'en': 'Build electronic circuits and watch the current flow in them.', 'hi': 'इलेक्ट्रॉनिक सर्किट बनाएँ और उनमें बहने वाली धारा को देखें।', 'kn': 'ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಸರ್ಕ್ಯೂಟ್‌ಗಳನ್ನು ನಿರ್ಮಿಸಿ ಮತ್ತು ಅವುಗಳಲ್ಲಿ ಪ್ರವಾಹ ಹರಿಯುವುದನ್ನು ನೋಡಿ.'},
  'circuitverse': {'en': 'Design digital circuits with logic gates, flip-flops and counters.', 'hi': 'लॉजिक गेट्स, फ्लिप-फ्लॉप और काउंटर के साथ डिजिटल सर्किट डिज़ाइन करें।', 'kn': 'ಲಾಜಿಕ್ ಗೇಟ್‌ಗಳು, ಫ್ಲಿಪ್-ಫ್ಲಾಪ್‌ಗಳು ಮತ್ತು ಕೌಂಟರ್‌ಗಳೊಂದಿಗೆ ಡಿಜಿಟಲ್ ಸರ್ಕ್ಯೂಟ್‌ಗಳನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಿ.'},
  'econgraphs': {'en': 'Move demand and supply curves and see the market respond.', 'hi': 'मांग और आपूर्ति वक्रों को स्थानांतरित करें और बाजार की प्रतिक्रिया देखें।', 'kn': 'ಬೇಡಿಕೆ ಮತ್ತು ಪೂರೈಕೆ ರೇಖೆಗಳನ್ನು ಚಲಾಯಿಸಿ ಮತ್ತು ಮಾರುಕಟ್ಟೆಯ ಪ್ರತಿಕ್ರಿಯೆಯನ್ನು ನೋಡಿ.'},
  'geo-quiz': {'en': 'Find Indian cities and places on the map.', 'hi': 'मानचित्र पर भारतीय शहर और स्थान ढूँढें।', 'kn': 'ನಕ್ಷೆಯಲ್ಲಿ ಭಾರತೀಯ ನಗರಗಳು ಮತ್ತು ಸ್ಥಳಗಳನ್ನು ಹುಡುಕಿ.'},
  'geogebra': {'en': 'Geometry, graphs and algebra in GeoGebra.', 'hi': 'GeoGebra में ज्यामिति, ग्राफ और बीजगणित।', 'kn': 'GeoGebra ದಲ್ಲಿ ಜ್ಯಾಮಿತಿ, ಗ್ರಾಫ್‌ಗಳು ಮತ್ತು ಬೀಜಗಣಿತ.'},
  'grammar': {'en': 'Check English sentences for grammar and spelling mistakes.', 'hi': 'व्याकरण और वर्तनी की अशुद्धियों के लिए अंग्रेजी वाक्यों की जाँच करें।', 'kn': 'ವ್ಯಾಕರಣ ಮತ್ತು ಕಾಗುಣಿತ ತಪ್ಪುಗಳಿಗಾಗಿ ಇಂಗ್ಲಿಷ್ ವಾಕ್ಯಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.'},
  'jsxgraph-geometry': {'en': 'Draw points, lines and circles and drag them to explore geometry.', 'hi': 'बिंदु, रेखाएँ और वृत्त बनाएँ और उन्हें खिसकाकर ज्यामिति समझें।', 'kn': 'ಬಿಂದುಗಳು, ರೇಖೆಗಳು ಮತ್ತು ವೃತ್ತಗಳನ್ನು ರಚಿಸಿ, ಅವುಗಳನ್ನು ಸರಿಸಿ ಜ್ಯಾಮಿತಿಯನ್ನು ಅನ್ವೇಷಿಸಿ.'},
  'jsxgraph-graph': {'en': 'Plot functions and change them with sliders.', 'hi': 'फलन आलेखित करें और स्लाइडर से उन्हें बदलें।', 'kn': 'ಫಂಕ್ಷನ್‌ಗಳನ್ನು ಪ್ಲಾಟ್ ಮಾಡಿ ಮತ್ತು ಸ್ಲೈಡರ್‌ಗಳೊಂದಿಗೆ ಅವುಗಳನ್ನು ಬದಲಾಯಿಸಿ.'},
  'jupyterlite': {'en': 'Write and run Python code on the board, with no internet.', 'hi': 'बिना इंटरनेट के, बोर्ड पर Python कोड लिखें और चलाएँ।', 'kn': 'ಇಂಟರ್ನೆಟ್ ಇಲ್ಲದೆ ಬೋರ್ಡ್‌ನಲ್ಲೇ Python ಕೋಡ್ ಬರೆದು ಚಲಾಯಿಸಿ.'},
  'labxchange': {'en': 'Virtual experiments and lessons in biology and chemistry.', 'hi': 'जीव विज्ञान और रसायन विज्ञान के आभासी प्रयोग और पाठ।', 'kn': 'ಜೀವಶಾಸ್ತ್ರ ಮತ್ತು ರಸಾಯನಶಾಸ್ತ್ರದ ವರ್ಚುವಲ್ ಪ್ರಯೋಗಗಳು ಮತ್ತು ಪಾಠಗಳು.'},
  'learningapps': {'en': 'Quizzes and learning games from LearningApps.', 'hi': 'LearningApps से क्विज़ और सीखने वाले खेल।', 'kn': 'LearningApps ನಿಂದ ರಸಪ್ರಶ್ನೆಗಳು ಮತ್ತು ಕಲಿಕಾ ಆಟಗಳು.'},
  'macro-money': {'en': 'See how banks create money through the money multiplier.', 'hi': 'देखें कि बैंक मुद्रा गुणक के ज़रिए धन का सृजन कैसे करते हैं।', 'kn': 'ಬ್ಯಾಂಕುಗಳು ಹಣ ಗುಣಕದ ಮೂಲಕ ಹಣವನ್ನು ಹೇಗೆ ಸೃಷ್ಟಿಸುತ್ತವೆ ಎಂದು ನೋಡಿ.'},
  'map-lab': {'en': 'Move around a world map, drop markers and measure distances.', 'hi': 'विश्व मानचित्र पर घूमें, मार्कर लगाएँ और दूरियाँ मापें।', 'kn': 'ವಿಶ್ವ ನಕ್ಷೆಯ ಸುತ್ತಲೂ ತಿರುಗಿ, ಗುರುತುಗಳನ್ನು ಇರಿಸಿ ಮತ್ತು ದೂರವನ್ನು ಅಳೆಯಿರಿ.'},
  'model3d': {'en': 'Open the board\'s 3D models of the body, plants and more.', 'hi': 'बोर्ड के शरीर, पौधों और अन्य के 3D मॉडल खोलें।', 'kn': 'ಬೋರ್ಡ್‌ನ ದೇಹ, ಸಸ್ಯಗಳು ಮತ್ತು ಹೆಚ್ಚಿನವುಗಳ 3D ಮಾದರಿಗಳನ್ನು ತೆರೆಯಿರಿ.'},
  'molstar': {'en': 'Turn and explore 3D structures of proteins and DNA.', 'hi': 'प्रोटीन और डीएनए की 3D संरचनाओं को घुमाकर देखें।', 'kn': 'ಪ್ರೋಟೀನ್‌ಗಳು ಮತ್ತು ಡಿಎನ್‌ಎಯ 3D ರಚನೆಗಳನ್ನು ತಿರುಗಿಸಿ ನೋಡಿ.'},
  'mw-diffusion': {'en': 'Drop dye into water and watch its molecules spread out.', 'hi': 'पानी में रंग की बूंद डालें और उसके अणुओं को फैलते हुए देखें।', 'kn': 'ನೀರಿಗೆ ಬಣ್ಣದ ಹನಿ ಹಾಕಿ ಮತ್ತು ಅದರ ಅಣುಗಳು ಹರಡುವುದನ್ನು ನೋಡಿ.'},
  'mw-gas-pressure': {'en': 'Squeeze a gas of moving molecules and watch its pressure rise.', 'hi': 'गतिशील अणुओं की गैस को दबाएं और इसका दाब बढ़ते हुए देखें।', 'kn': 'ಚಲಿಸುವ ಅಣುಗಳ ಅನಿಲವನ್ನು ಒತ್ತಿ ಮತ್ತು ಅದರ ಒತ್ತಡ ಹೆಚ್ಚಾಗುವುದನ್ನು ನೋಡಿ.'},
  'mw-gas-temperature': {'en': 'Heat a gas of moving molecules and watch it expand.', 'hi': 'गतिशील अणुओं की गैस को गर्म करें और इसे फैलते हुए देखें।', 'kn': 'ಚಲಿಸುವ ಅಣುಗಳ ಅನಿಲವನ್ನು ಬಿಸಿ ಮಾಡಿ ಮತ್ತು ಅದು ಹಿಗ್ಗುವುದನ್ನು ನೋಡಿ.'},
  'mw-membrane': {'en': 'See which molecules pass through a membrane with small holes.', 'hi': 'देखें कि छोटे छेदों वाली झिल्ली से कौन से अणु गुजरते हैं।', 'kn': 'ಸಣ್ಣ ರಂಧ್ರಗಳಿರುವ ಪೊರೆಯ ಮೂಲಕ ಯಾವ ಅಣುಗಳು ಹಾದುಹೋಗುತ್ತವೆ ಎಂದು ನೋಡಿ.'},
  'mw-oil-water': {'en': 'See why oil and water molecules do not mix.', 'hi': 'देखें कि तेल और पानी के अणु क्यों नहीं मिलते हैं।', 'kn': 'ಎಣ್ಣೆ ಮತ್ತು ನೀರಿನ ಅಣುಗಳು ಏಕೆ ಮಿಶ್ರಣಗೊಳ್ಳುವುದಿಲ್ಲ ಎಂದು ನೋಡಿ.'},
  'mw-phase-change': {'en': 'Add energy to molecules and watch a solid melt and then boil.', 'hi': 'अणुओं को ऊर्जा दें और ठोस को पिघलते तथा उबलते हुए देखें।', 'kn': 'ಅಣುಗಳಿಗೆ ಶಕ್ತಿ ನೀಡಿ ಮತ್ತು ಘನವು ಕರಗುವುದನ್ನು ಹಾಗೂ ಕುದಿಯುವುದನ್ನು ನೋಡಿ.'},
  'osp': {'en': 'Physics simulations from the Open Source Physics collection.', 'hi': 'Open Source Physics संग्रह से भौतिकी सिमुलेशन।', 'kn': 'Open Source Physics ಸಂಗ್ರಹದಿಂದ ಭೌತಶಾಸ್ತ್ರದ ಸಿಮ್ಯುಲೇಶನ್‌ಗಳು.'},
  'pavlovia': {'en': 'Run psychology experiments made with PsychoPy.', 'hi': 'PsychoPy से बने मनोविज्ञान प्रयोग चलाएँ।', 'kn': 'PsychoPy ನೊಂದಿಗೆ ತಯಾರಿಸಿದ ಮನೋವಿಜ್ಞಾನ ಪ್ರಯೋಗಗಳನ್ನು ನಡೆಸಿ.'},
  'pebl-reaction': {'en': 'Tap as soon as the screen turns green and measure your reaction time.', 'hi': 'स्क्रीन हरी होते ही टैप करें और अपना प्रतिक्रिया समय मापें।', 'kn': 'ಪರದೆಯು ಹಸಿರು ಬಣ್ಣಕ್ಕೆ ತಿರುಗಿದ ತಕ್ಷಣ ಟ್ಯಾಪ್ ಮಾಡಿ ಮತ್ತು ನಿಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯವನ್ನು ಅಳೆಯಿರಿ.'},
  'pebl-span': {'en': 'Remember longer and longer strings of digits.', 'hi': 'अंकों की लंबी से लंबी श्रृंखलाओं को याद रखें।', 'kn': 'ಹೆಚ್ಚುತ್ತಾ ಹೋಗುವ ಅಂಕಿಗಳ ಸರಣಿಯನ್ನು ನೆನಪಿಡಿ.'},
  'pebl-stroop': {'en': 'Name the ink colour of colour words and measure the Stroop effect.', 'hi': 'रंगों के नाम वाले शब्दों की स्याही का रंग बताएँ और स्ट्रूप प्रभाव मापें।', 'kn': 'ಬಣ್ಣದ ಹೆಸರಿನ ಪದಗಳ ಶಾಯಿಯ ಬಣ್ಣವನ್ನು ಹೇಳಿ, ಸ್ಟ್ರೂಪ್ ಪರಿಣಾಮವನ್ನು ಅಳೆಯಿರಿ.'},
  'phet-acid-base-solutions': {'en': 'Compare strong and weak acids and bases by pH and conductivity.', 'hi': 'पीएच और चालकता से प्रबल और दुर्बल अम्लों तथा क्षारकों की तुलना करें।', 'kn': 'ಪಿಎಚ್ ಮತ್ತು ವಾಹಕತೆಯ ಮೂಲಕ ಪ್ರಬಲ ಹಾಗೂ ದುರ್ಬಲ ಆಮ್ಲಗಳು ಮತ್ತು ಪ್ರತ್ಯಾಮ್ಲಗಳನ್ನು ಹೋಲಿಸಿ.'},
  'phet-all': {'en': 'Browse every PhET simulation on PhET\'s website.', 'hi': 'PhET की वेबसाइट पर सभी PhET सिमुलेशन देखें।', 'kn': 'PhET ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ಪ್ರತಿಯೊಂದು PhET ಸಿಮ್ಯುಲೇಶನ್ ಅನ್ನು ವೀಕ್ಷಿಸಿ.'},
  'phet-area-builder': {'en': 'Build shapes with unit squares and find their area and perimeter.', 'hi': 'इकाई वर्गों के साथ आकृतियाँ बनाएं और उनका क्षेत्रफल तथा परिमाप ज्ञात करें।', 'kn': 'ಘಟಕ ಚೌಕಗಳೊಂದಿಗೆ ಆಕೃತಿಗಳನ್ನು ನಿರ್ಮಿಸಿ ಮತ್ತು ಅವುಗಳ ವಿಸ್ತೀರ್ಣ ಹಾಗೂ ಸುತ್ತಳತೆಯನ್ನು ಕಂಡುಹಿಡಿಯಿರಿ.'},
  'phet-arithmetic': {'en': 'Practise multiplication, factors and division in a game.', 'hi': 'एक खेल में गुणा, गुणनखंड और भाग का अभ्यास करें।', 'kn': 'ಆಟವೊಂದರಲ್ಲಿ ಗುಣಾಕಾರ, ಅಪವರ್ತನಗಳು ಮತ್ತು ಭಾಗಾಕಾರವನ್ನು ಅಭ್ಯಾಸ ಮಾಡಿ.'},
  'phet-balancing-chemical-equations': {'en': 'Balance chemical equations by changing the numbers of molecules.', 'hi': 'अणुओं की संख्या बदलकर रासायनिक समीकरणों को संतुलित करें।', 'kn': 'ಅಣುಗಳ ಸಂಖ್ಯೆಯನ್ನು ಬದಲಾಯಿಸುವ ಮೂಲಕ ರಾಸಾಯನಿಕ ಸಮೀಕರಣಗಳನ್ನು ತುಲನೆ ಮಾಡಿ.'},
  'phet-balloons-and-static-electricity': {'en': 'Rub a balloon on a sweater and see charges move and attract.', 'hi': 'स्वेटर पर गुब्बारा रगड़ें और आवेशों को गति करते तथा आकर्षित होते हुए देखें।', 'kn': 'ಸ್ವೆಟರ್ ಮೇಲೆ ಬಲೂನ್ ಅನ್ನು ಉಜ್ಜಿ ಮತ್ತು ಆವೇಶಗಳು ಚಲಿಸುವುದನ್ನು ಹಾಗೂ ಆಕರ್ಷಿಸುವುದನ್ನು ನೋಡಿ.'},
  'phet-bending-light': {'en': 'Shine a laser into glass and water to see reflection and refraction.', 'hi': 'परावर्तन और अपवर्तन देखने के लिए कांच और पानी पर लेज़र डालें।', 'kn': 'ಪ್ರತಿಫಲನ ಮತ್ತು ವಕ್ರೀಭವನವನ್ನು ನೋಡಲು ಗಾಜು ಮತ್ತು ನೀರಿನ ಮೇಲೆ ಲೇಸರ್ ಬೆಳಕನ್ನು ಹಾಯಿಸಿ.'},
  'phet-blackbody-spectrum': {'en': 'See how the light from a hot object changes with its temperature.', 'hi': 'देखें कि गर्म वस्तु से निकलने वाला प्रकाश उसके तापमान के साथ कैसे बदलता है।', 'kn': 'ಬಿಸಿಯಾದ ವಸ್ತುವಿನಿಂದ ಬರುವ ಬೆಳಕು ಅದರ ತಾಪಮಾನದೊಂದಿಗೆ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-build-a-fraction': {'en': 'Build fractions from shapes and numbers.', 'hi': 'आकृतियों और संख्याओं से भिन्न बनाएं।', 'kn': 'ಆಕೃತಿಗಳು ಮತ್ತು ಸಂಖ್ಯೆಗಳಿಂದ ಭಿನ್ನರಾಶಿಗಳನ್ನು ನಿರ್ಮಿಸಿ.'},
  'phet-build-an-atom': {'en': 'Put protons, neutrons and electrons together to make atoms and ions.', 'hi': 'परमाणु और आयन बनाने के लिए प्रोटॉन, न्यूट्रॉन और इलेक्ट्रॉन को एक साथ रखें।', 'kn': 'ಪರಮಾಣುಗಳು ಮತ್ತು ಅಯಾನುಗಳನ್ನು ಮಾಡಲು ಪ್ರೋಟಾನ್‌ಗಳು, ನ್ಯೂಟ್ರಾನ್‌ಗಳು ಮತ್ತು ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳನ್ನು ಸೇರಿಸಿ.'},
  'phet-charges-and-fields': {'en': 'Place charges and see the electric field and voltage around them.', 'hi': 'आवेश रखें और उनके चारों ओर विद्युत क्षेत्र तथा विभव देखें।', 'kn': 'ಆವೇಶಗಳನ್ನು ಇರಿಸಿ ಮತ್ತು ಅವುಗಳ ಸುತ್ತಲಿನ ವಿದ್ಯುತ್ ಕ್ಷೇತ್ರ ಹಾಗೂ ವಿಭವವನ್ನು ನೋಡಿ.'},
  'phet-circuit-construction-kit-dc': {'en': 'Build circuits with batteries, bulbs, switches and resistors and measure current and voltage.', 'hi': 'बैटरी, बल्ब, स्विच और रेसिस्टर के साथ सर्किट बनाएं और करंट और वोल्टेज मापें।', 'kn': 'ಬ್ಯಾಟರಿಗಳು, ದೀಪಗಳು, ಸ್ವಿಚ್‌ಗಳು ಮತ್ತು ರೋಧಕಗಳೊಂದಿಗೆ ವಿದ್ಯುತ್ ಮಂಡಲಗಳನ್ನು ನಿರ್ಮಿಸಿ ಮತ್ತು ಪ್ರವಾಹ ಹಾಗೂ ವೋಲ್ಟೇಜ್ ಅನ್ನು ಅಳೆಯಿರಿ.'},
  'phet-collision-lab': {'en': 'Collide balls and explore momentum and kinetic energy.', 'hi': 'गेंदों की टक्कर कराएं और संवेग तथा गतिज ऊर्जा का अध्ययन करें।', 'kn': 'ಚೆಂಡುಗಳನ್ನು ಡಿಕ್ಕಿಹೊಡಿಸಿ ಮತ್ತು ಸಂವೇಗ ಹಾಗೂ ಚಲನ ಶಕ್ತಿಯನ್ನು ಅನ್ವೇಷಿಸಿ.'},
  'phet-color-vision': {'en': 'Mix red, green and blue light and see the colour a person sees.', 'hi': 'लाल, हरे और नीले प्रकाश को मिलाएं तथा वह रंग देखें जो व्यक्ति को दिखाई देता है।', 'kn': 'ಕೆಂಪು, ಹಸಿರು ಮತ್ತು ನೀಲಿ ಬೆಳಕನ್ನು ಬೆರೆಸಿ ಮತ್ತು ವ್ಯಕ್ತಿಗೆ ಕಾಣುವ ಬಣ್ಣವನ್ನು ನೋಡಿ.'},
  'phet-density': {'en': 'Compare blocks of different mass and volume and see which ones float.', 'hi': 'अलग-अलग द्रव्यमान और आयतन के गुटकों की तुलना करें और देखें कि कौन से तैरते हैं।', 'kn': 'ವಿಭಿನ್ನ ದ್ರವ್ಯರಾಶಿ ಮತ್ತು ಗಾತ್ರದ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಹೋಲಿಸಿ ಮತ್ತು ಯಾವುವು ತೇಲುತ್ತವೆ ಎಂದು ನೋಡಿ.'},
  'phet-energy-forms-and-changes': {'en': 'Heat, cool and pass energy between objects and systems.', 'hi': 'वस्तुओं को गर्म और ठंडा करें और उनके तथा निकायों के बीच ऊर्जा का स्थानांतरण देखें।', 'kn': 'ವಸ್ತುಗಳನ್ನು ಬಿಸಿ ಮತ್ತು ತಣ್ಣಗೆ ಮಾಡಿ, ವಸ್ತುಗಳು ಮತ್ತು ವ್ಯವಸ್ಥೆಗಳ ನಡುವೆ ಶಕ್ತಿಯ ವರ್ಗಾವಣೆಯನ್ನು ನೋಡಿ.'},
  'phet-energy-skate-park-basics': {'en': 'Watch a skater turn potential energy into kinetic energy on a ramp.', 'hi': 'एक रैंप पर स्केटर को स्थितिज ऊर्जा को गतिज ऊर्जा में बदलते हुए देखें।', 'kn': 'ಇಳಿಜಾರಿನಲ್ಲಿ ಸ್ಕೇಟರ್ ಸ್ಥಿತಿಜ ಶಕ್ತಿಯನ್ನು ಚಲನ ಶಕ್ತಿಯಾಗಿ ಪರಿವರ್ತಿಸುವುದನ್ನು ನೋಡಿ.'},
  'phet-equality-explorer': {'en': 'Keep a balance level to solve equations.', 'hi': 'समीकरण हल करने के लिए तराजू को संतुलित रखें।', 'kn': 'ಸಮೀಕರಣಗಳನ್ನು ಬಿಡಿಸಲು ತಕ್ಕಡಿಯನ್ನು ಸಮತೋಲನದಲ್ಲಿಡಿ.'},
  'phet-faradays-law': {'en': 'Move a magnet through a coil and light a bulb with the induced current.', 'hi': 'एक चुंबक को कुंडली से गुजारें और प्रेरित धारा से बल्ब जलाएं।', 'kn': 'ಸುರುಳಿಯ ಮೂಲಕ ಕಾಂತವನ್ನು ಚಲಾಯಿಸಿ ಮತ್ತು ಪ್ರೇರಿತ ವಿದ್ಯುತ್‌ನಿಂದ ದೀಪವನ್ನು ಬೆಳಗಿಸಿ.'},
  'phet-forces-and-motion-basics': {'en': 'Push objects and play tug of war to see how forces change motion.', 'hi': 'वस्तुओं को धकेलें और रस्साकशी खेलें, देखें कि बल गति को कैसे बदलते हैं।', 'kn': 'ವಸ್ತುಗಳನ್ನು ತಳ್ಳಿ ಮತ್ತು ಹಗ್ಗ ಜಗ್ಗಾಟ ಆಡಿ, ಬಲಗಳು ಚಲನೆಯನ್ನು ಹೇಗೆ ಬದಲಿಸುತ್ತವೆ ಎಂದು ನೋಡಿ.'},
  'phet-fractions-intro': {'en': 'Show fractions with circles, bars and cups and match them.', 'hi': 'वृत्तों, पट्टी और कपों के साथ भिन्न दिखाएं और उनका मिलान करें।', 'kn': 'ವೃತ್ತಗಳು, ಪಟ್ಟಿಗಳು ಮತ್ತು ಕಪ್‌ಗಳೊಂದಿಗೆ ಭಿನ್ನರಾಶಿಗಳನ್ನು ತೋರಿಸಿ ಮತ್ತು ಅವುಗಳನ್ನು ಹೊಂದಿಸಿ.'},
  'phet-friction': {'en': 'Rub two surfaces together and watch the atoms heat up and break away.', 'hi': 'दो सतहों को आपस में रगड़ें और परमाणुओं को गर्म होते तथा टूटते हुए देखें।', 'kn': 'ಎರಡು ಮೇಲ್ಮೈಗಳನ್ನು ಪರಸ್ಪರ ಉಜ್ಜಿ ಮತ್ತು ಪರಮಾಣುಗಳು ಬಿಸಿಯಾಗುವುದನ್ನು ಹಾಗೂ ಬೇರ್ಪಡುವುದನ್ನು ನೋಡಿ.'},
  'phet-function-builder': {'en': 'Send inputs through function machines and find the rule.', 'hi': 'फलन मशीनों के माध्यम से इनपुट भेजें और नियम खोजें।', 'kn': 'ಫಂಕ್ಷನ್ ಯಂತ್ರಗಳ ಮೂಲಕ ಇನ್‌ಪುಟ್‌ಗಳನ್ನು ಕಳುಹಿಸಿ ಮತ್ತು ನಿಯಮವನ್ನು ಹುಡುಕಿ.'},
  'phet-gene-expression-essentials': {'en': 'Follow a gene from DNA to protein inside a cell.', 'hi': 'कोशिका के भीतर डीएनए से प्रोटीन तक एक जीन की यात्रा देखें।', 'kn': 'ಕೋಶದೊಳಗೆ ಡಿಎನ್‌ಎಯಿಂದ ಪ್ರೋಟೀನ್‌ವರೆಗೆ ಒಂದು ಜೀನ್‌ನ ಪಯಣವನ್ನು ಅನುಸರಿಸಿ.'},
  'phet-geometric-optics': {'en': 'Move an object in front of a lens or mirror and see where the image forms.', 'hi': 'लेंस या दर्पण के सामने वस्तु को रखें और देखें कि प्रतिबिंब कहाँ बनता है।', 'kn': 'ಮಸೂರ ಅಥವಾ ದರ್ಪಣದ ಮುಂದೆ ವಸ್ತುವನ್ನು ಇರಿಸಿ ಮತ್ತು ಪ್ರತಿಬಿಂಬ ಎಲ್ಲಿ ರೂಪುಗೊಳ್ಳುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-graphing-lines': {'en': 'Plot straight lines and explore slope and intercept.', 'hi': 'सरल रेखाएं खींचें और ढाल तथा अंतःखंड का अध्ययन करें।', 'kn': 'ಸರಳ ರೇಖೆಗಳನ್ನು ಗ್ರಾಫ್‌ನಲ್ಲಿ ಎಳೆಯಿರಿ ಮತ್ತು ಇಳಿಜಾರು ಹಾಗೂ ಅಂತಃಖಂಡವನ್ನು ಅನ್ವೇಷಿಸಿ.'},
  'phet-graphing-quadratics': {'en': 'Plot parabolas and explore the vertex, roots and axis of symmetry.', 'hi': 'परवलय खींचें और शीर्ष, मूल तथा समरूपता अक्ष का अध्ययन करें।', 'kn': 'ಪರವಲಯಗಳನ್ನು ಗ್ರಾಫ್‌ನಲ್ಲಿ ಎಳೆಯಿರಿ ಮತ್ತು ಶೃಂಗ, ಮೂಲಗಳು ಹಾಗೂ ಸಮಮಿತಿಯ ಅಕ್ಷವನ್ನು ಅನ್ವೇಷಿಸಿ.'},
  'phet-gravity-and-orbits': {'en': 'Move the Sun, Earth and Moon and see how gravity keeps them in orbit.', 'hi': 'सूर्य, पृथ्वी और चंद्रमा को घुमाएं और देखें कि गुरुत्वाकर्षण उन्हें कक्षा में कैसे रखता है।', 'kn': 'ಸೂರ್ಯ, ಭೂಮಿ ಮತ್ತು ಚಂದ್ರರನ್ನು ಚಲಾಯಿಸಿ ಮತ್ತು ಗುರುತ್ವಾಕರ್ಷಣೆಯು ಅವುಗಳನ್ನು ಕಕ್ಷೆಯಲ್ಲಿ ಹೇಗೆ ಹಿಡಿದಿಟ್ಟುಕೊಳ್ಳುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-gravity-force-lab': {'en': 'Change the masses and the distance and measure the gravitational force.', 'hi': 'द्रव्यमान और दूरी बदलें तथा गुरुत्वाकर्षण बल मापें।', 'kn': 'ದ್ರವ್ಯರಾಶಿಗಳು ಮತ್ತು ದೂರವನ್ನು ಬದಲಾಯಿಸಿ ಹಾಗೂ ಗುರುತ್ವಾಕರ್ಷಣಾ ಬಲವನ್ನು ಅಳತೆ ಮಾಡಿ.'},
  'phet-greenhouse-effect': {'en': 'See how greenhouse gases trap heat and warm the Earth.', 'hi': 'देखें कि ग्रीनहाउस गैसें कैसे गर्मी रोकती हैं और पृथ्वी को गर्म करती हैं।', 'kn': 'ಹಸಿರುಮನೆ ಅನಿಲಗಳು ಶಾಖವನ್ನು ಹೇಗೆ ಹಿಡಿದಿಟ್ಟುಕೊಳ್ಳುತ್ತವೆ ಮತ್ತು ಭೂಮಿಯನ್ನು ಹೇಗೆ ಬೆಚ್ಚಗಾಗಿಸುತ್ತವೆ ಎಂದು ನೋಡಿ.'},
  'phet-hookes-law': {'en': 'Stretch and compress springs and see how force and length are related.', 'hi': 'स्प्रिंग को खींचें और दबाएं तथा देखें कि बल और लंबाई कैसे संबंधित हैं।', 'kn': 'ಸ್ಪ್ರಿಂಗ್‌ಗಳನ್ನು ಎಳೆದು ಕುಗ್ಗಿಸಿ ಮತ್ತು ಬಲ ಹಾಗೂ ಉದ್ದವು ಹೇಗೆ ಸಂಬಂಧಿಸಿವೆ ಎಂದು ನೋಡಿ.'},
  'phet-isotopes-and-atomic-mass': {'en': 'Make isotopes and see how they set an element\'s average atomic mass.', 'hi': 'समस्थानिक बनाएं और देखें कि वे किसी तत्व का औसत परमाणु द्रव्यमान कैसे तय करते हैं।', 'kn': 'ಸಮಸ್ಥಾನಿಗಳನ್ನು ಸಿದ್ಧಪಡಿಸಿ ಮತ್ತು ಅವು ಧಾತುವಿನ ಸರಾಸರಿ ಪರಮಾಣು ದ್ರವ್ಯರಾಶಿಯನ್ನು ಹೇಗೆ ನಿರ್ಧರಿಸುತ್ತವೆ ಎಂದು ನೋಡಿ.'},
  'phet-john-travoltage': {'en': 'Rub John\'s foot on the carpet and see the spark when he touches the door handle.', 'hi': 'कारपेट पर जॉन का पैर रगड़ें और दरवाजे के हैंडल को छूने पर चिंगारी देखें।', 'kn': 'ಜಾನ್‌ನ ಕಾಲನ್ನು ಕಾರ್ಪೆಟ್ ಮೇಲೆ ಉಜ್ಜಿ, ಅವನು ಬಾಗಿಲಿನ ಹಿಡಿಕೆ ಮುಟ್ಟಿದಾಗ ಕಿಡಿ ಹಾರುವುದನ್ನು ನೋಡಿ.'},
  'phet-least-squares-regression': {'en': 'Fit a line to data points and see how good the fit is.', 'hi': 'डेटा बिंदुओं पर एक रेखा फिट करें और देखें कि फिट कितना अच्छा है।', 'kn': 'ದತ್ತಾಂಶ ಬಿಂದುಗಳಿಗೆ ರೇಖೆಯೊಂದನ್ನು ಹೊಂದಿಸಿ ಮತ್ತು ಆ ಹೊಂದಾಣಿಕೆಯು ಎಷ್ಟು ಉತ್ತಮವಾಗಿದೆ ಎಂದು ನೋಡಿ.'},
  'phet-magnet-and-compass': {'en': 'Move a bar magnet and see its field lines and where a compass points.', 'hi': 'एक छड़ चुंबक को घुमाएं और उसकी क्षेत्र रेखाओं तथा कंपास की दिशा को देखें।', 'kn': 'ದಂಡಕಾಂತವನ್ನು ಸರಿಸಿ, ಅದರ ಕಾಂತೀಯ ಬಲರೇಖೆಗಳನ್ನು ಮತ್ತು ದಿಕ್ಸೂಚಿ ತೋರುವ ದಿಕ್ಕನ್ನು ನೋಡಿ.'},
  'phet-masses-and-springs': {'en': 'Hang masses on springs and explore oscillation and energy.', 'hi': 'स्प्रिंग पर द्रव्यमान लटकाएं और दोलन तथा ऊर्जा का अध्ययन करें।', 'kn': 'ಸ್ಪ್ರಿಂಗ್‌ಗಳಿಗೆ ದ್ರವ್ಯರಾಶಿಗಳನ್ನು ತೂಗುಹಾಕಿ ಮತ್ತು ಆಂದೋಲನ ಹಾಗೂ ಶಕ್ತಿಯನ್ನು ಅನ್ವೇಷಿಸಿ.'},
  'phet-molarity': {'en': 'Dissolve a solute and see how the amount and the volume set the concentration.', 'hi': 'विलेय घोलें और देखें कि मात्रा और आयतन सांद्रता कैसे तय करते हैं।', 'kn': 'ದ್ರಾವ್ಯವನ್ನು ಕರಗಿಸಿ ಮತ್ತು ಪ್ರಮಾಣ ಹಾಗೂ ಗಾತ್ರವು ಸಾಂದ್ರತೆಯನ್ನು ಹೇಗೆ ನಿರ್ಧರಿಸುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-molecule-polarity': {'en': 'See how the electronegativity of atoms makes a molecule polar.', 'hi': 'देखें कि परमाणुओं की विद्युत ऋणात्मकता एक अणु को ध्रुवीय कैसे बनाती है।', 'kn': 'ಪರಮಾಣುಗಳ ವಿದ್ಯುದೃಣತೆಯು ಅಣುವನ್ನು ಹೇಗೆ ಧ್ರುವೀಯವನ್ನಾಗಿ ಮಾಡುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-molecule-shapes': {'en': 'Build molecules in 3D and see how electron pairs set their shapes.', 'hi': '3D में अणु बनाएं और देखें कि इलेक्ट्रॉन युग्म उनके आकार कैसे तय करते हैं।', 'kn': '3D ಯಲ್ಲಿ ಅಣುಗಳನ್ನು ನಿರ್ಮಿಸಿ ಮತ್ತು ಎಲೆಕ್ಟ್ರಾನ್ ಜೋಡಿಗಳು ಅವುಗಳ ಆಕಾರವನ್ನು ಹೇಗೆ ನಿರ್ಧರಿಸುತ್ತವೆ ಎಂದು ನೋಡಿ.'},
  'phet-natural-selection': {'en': 'Watch a rabbit population change as mutations meet wolves and food shortages.', 'hi': 'भेड़ियों और भोजन की कमी का सामना करने पर खरगोश की आबादी को बदलते हुए देखें।', 'kn': 'ತೋಳಗಳು ಮತ್ತು ಆಹಾರದ ಕೊರತೆಯನ್ನು ಎದುರಿಸಿದಾಗ ಮೊಲಗಳ ಸಂಖ್ಯೆ ಬದಲಾಗುವುದನ್ನು ನೋಡಿ.'},
  'phet-neuron': {'en': 'Stimulate a neuron and watch a nerve impulse travel along it.', 'hi': 'न्यूरॉन को उत्तेजित करें और इसके साथ तंत्रिका आवेग को यात्रा करते हुए देखें।', 'kn': 'ನ್ಯೂರಾನ್ ಅನ್ನು ಉತ್ತೇಜಿಸಿ ಮತ್ತು ಅದರ ಮೂಲಕ ನರ ಸಂಕೇತವು ಚಲಿಸುವುದನ್ನು ನೋಡಿ.'},
  'phet-ohms-law': {'en': 'Change the voltage and resistance and see the current change, V = IR.', 'hi': 'विभवांतर और प्रतिरोध बदलें और धारा को बदलते देखें, V = IR।', 'kn': 'ವಿಭವಾಂತರ ಮತ್ತು ರೋಧವನ್ನು ಬದಲಿಸಿ, ವಿದ್ಯುತ್ ಪ್ರವಾಹ ಬದಲಾಗುವುದನ್ನು ನೋಡಿ, V = IR.'},
  'phet-pendulum-lab': {'en': 'Change the length, mass and gravity of a pendulum and time its swings.', 'hi': 'पेंडुलम की लंबाई, द्रव्यमान और गुरुत्वाकर्षण को बदलें और उसके दोलनों का समय मापें।', 'kn': 'ಲೋಲಕದ ಉದ್ದ, ರಾಶಿ ಮತ್ತು ಗುರುತ್ವವನ್ನು ಬದಲಿಸಿ, ಅದರ ಆಂದೋಲನಗಳ ಸಮಯವನ್ನು ಅಳೆಯಿರಿ.'},
  'phet-ph-scale': {'en': 'Test everyday liquids and find out whether they are acids or bases.', 'hi': 'रोजमर्रा के तरल पदार्थों का परीक्षण करें और पता लगाएं कि वे अम्ल हैं या क्षारक।', 'kn': 'ದೈನಂದಿನ ದ್ರವಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ ಮತ್ತು ಅವು ಆಮ್ಲಗಳೇ ಅಥವಾ ಪ್ರತ್ಯಾಮ್ಲಗಳೇ ಎಂದು ಕಂಡುಹಿಡಿಯಿರಿ.'},
  'phet-plinko-probability': {'en': 'Drop balls through pegs and watch the normal distribution build up.', 'hi': 'कीलों के बीच से गेंदें गिराएँ और प्रसामान्य बंटन बनते हुए देखें।', 'kn': 'ಮೊಳೆಗಳ ನಡುವೆ ಚೆಂಡುಗಳನ್ನು ಬೀಳಿಸಿ, ಸಾಮಾನ್ಯ ವಿತರಣೆ ರೂಪುಗೊಳ್ಳುವುದನ್ನು ನೋಡಿ.'},
  'phet-projectile-motion': {'en': 'Launch objects from a cannon and see how angle, speed and air resistance change the path.', 'hi': 'तोप से वस्तुएं लॉन्च करें और देखें कि कोण, गति और वायु प्रतिरोध पथ को कैसे बदलते हैं।', 'kn': 'ಫಿರಂಗಿಯಿಂದ ವಸ್ತುಗಳನ್ನು ಹಾರಿಸಿ ಮತ್ತು ಕೋನ, ವೇಗ ಹಾಗೂ ಗಾಳಿಯ ರೋಧವು ಪಥವನ್ನು ಹೇಗೆ ಬದಲಾಯಿಸುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-reactants-products-and-leftovers': {'en': 'See which reactant runs out first and what is left over.', 'hi': 'देखें कि कौन सा अभिकारक पहले समाप्त होता है और क्या शेष बचता है।', 'kn': 'ಯಾವ ಪ್ರತಿಕಾರಕವು ಮೊದಲು ಖಾಲಿಯಾಗುತ್ತದೆ ಮತ್ತು ಯಾವುದು ಉಳಿದುಕೊಳ್ಳುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-sound-waves': {'en': 'See sound travel as pressure waves and how frequency changes the pitch.', 'hi': 'देखें कि ध्वनि दाब तरंगों के रूप में कैसे चलती है और आवृत्ति तारत्व को कैसे बदलती है।', 'kn': 'ಶಬ್ದವು ಒತ್ತಡದ ಅಲೆಗಳಾಗಿ ಹೇಗೆ ಚಲಿಸುತ್ತದೆ ಮತ್ತು ಆವೃತ್ತಿಯು ತಾರತ್ವವನ್ನು ಹೇಗೆ ಬದಲಿಸುತ್ತದೆ ಎಂದು ನೋಡಿ.'},
  'phet-states-of-matter': {'en': 'Heat and cool atoms and molecules to see solids, liquids and gases.', 'hi': 'ठोस, द्रव और गैस देखने के लिए परमाणुओं और अणुओं को गर्म तथा ठंडा करें।', 'kn': 'ಘನ, ದ್ರವ ಮತ್ತು ಅನಿಲಗಳನ್ನು ನೋಡಲು ಪರಮಾಣುಗಳು ಮತ್ತು ಅಣುಗಳನ್ನು ಬಿಸಿ ಮತ್ತು ತಣ್ಣಗೆ ಮಾಡಿ.'},
  'phet-vector-addition': {'en': 'Add vectors tip to tail and read their components.', 'hi': 'सदिशों को सिरे से सिरा मिलाकर जोड़ें और उनके घटक पढ़ें।', 'kn': 'ಸದಿಶಗಳನ್ನು ತುದಿಯಿಂದ ತುದಿಗೆ ಸೇರಿಸಿ ಮತ್ತು ಅವುಗಳ ಘಟಕಗಳನ್ನು ಓದಿ.'},
  'phet-wave-on-a-string': {'en': 'Shake a string and watch waves move, reflect and form standing waves.', 'hi': 'एक डोरी को हिलाएँ और तरंगों को चलते, परावर्तित होते और अप्रगामी तरंगें बनाते देखें।', 'kn': 'ದಾರವನ್ನು ಅಲುಗಾಡಿಸಿ, ಅಲೆಗಳು ಚಲಿಸುವುದನ್ನು, ಪ್ರತಿಫಲಿಸುವುದನ್ನು ಮತ್ತು ನಿಂತ ಅಲೆಗಳು ರೂಪುಗೊಳ್ಳುವುದನ್ನು ನೋಡಿ.'},
  'phet-waves-intro': {'en': 'Make water, sound and light waves and compare them.', 'hi': 'पानी, ध्वनि और प्रकाश की तरंगें बनाएं तथा उनकी तुलना करें।', 'kn': 'ನೀರು, ಶಬ್ದ ಮತ್ತು ಬೆಳಕಿನ ಅಲೆಗಳನ್ನು ಸೃಷ್ಟಿಸಿ ಹಾಗೂ ಅವುಗಳನ್ನು ಹೋಲಿಸಿ.'},
  'polypad': {'en': 'Tiles, shapes and number tools for hands-on maths.', 'hi': 'हाथों-हाथ गणित सीखने के लिए टाइल्स, आकृतियाँ और संख्या उपकरण।', 'kn': 'ನೇರ ಗಣಿತ ಕಲಿಕೆಗಾಗಿ ಟೈಲ್ಸ್‌ಗಳು, ಆಕಾರಗಳು ಮತ್ತು ಸಂಖ್ಯೆ ಉಪಕರಣಗಳು.'},
  'timeline': {'en': 'Draw a timeline from the board\'s key dates.', 'hi': 'बोर्ड की मुख्य तिथियों से समय-रेखा बनाएँ।', 'kn': 'ಬೋರ್ಡ್‌ನ ಪ್ರಮುಖ ದಿನಾಂಕಗಳಿಂದ ಕಾಲರೇಖೆಯನ್ನು ಎಳೆಯಿರಿ.'},
  'timelinejs': {'en': 'Make a timeline of events with dates and pictures.', 'hi': 'तारीखों और चित्रों के साथ घटनाओं की समयरेखा बनाएँ।', 'kn': 'ದಿನಾಂಕಗಳು ಮತ್ತು ಚಿತ್ರಗಳೊಂದಿಗೆ ಘಟನೆಗಳ ಕಾಲರೇಖೆಯನ್ನು ತಯಾರಿಸಿ.'},
  'wokwi': {'en': 'Build and program Arduino and ESP32 projects.', 'hi': 'Arduino और ESP32 प्रोजेक्ट बनाएँ और प्रोग्राम करें।', 'kn': 'Arduino ಮತ್ತು ESP32 ಪ್ರಾಜೆಕ್ಟ್‌ಗಳನ್ನು ನಿರ್ಮಿಸಿ ಮತ್ತು ಪ್ರೋಗ್ರಾಮ್ ಮಾಡಿ.'},
};
